INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.start.prologue.promoted.t7', 'scene.start.prologue', 'scene', 'caption', 'chairman', NULL, NULL, NULL, 'start.prologue.t7', 'male', 'Выбран avatar.key = promoted; адрес пролога 3:56.', 'scene.start.prologue.promoted.t6', 'Люди уже приглядываются, кого им прислали. Первое впечатление лучше не портить.', 'Дорожный пролог, 3:56. Слева уже слышно голодных коров; жители у дороги молча смотрят вслед телеге. Внутренняя мысль аватара «Партийный выдвиженец»; показывается текстом без озвучки.', 'Скоту не хватает корма, а жители только наблюдают за новым председателем.', 'Дать первый живой сигнал хозяйственной беды и реакцию аватара на молчаливую встречу.', 'Уверенная речь человека со связями и привычкой к согласованиям; канцелярит не должен становиться пародией. Не угадывать мысли жителей и не утверждать, что они уже что-либо рассказали.', 'ai/prologue-avatar-thoughts-draft.md#8-партийный-выдвиженец', 1, NULL, 0, 705);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.start.prologue.promoted.t8', 'scene.start.prologue', 'scene', 'caption', 'chairman', NULL, NULL, NULL, 'start.prologue.t8', 'male', 'Выбран avatar.key = promoted; адрес пролога 4:44.', 'scene.start.prologue.promoted.t7', 'Встреча у полуразвалившейся церкви. О такой разрухе в районе почему-то не доложили.', 'Дорожный пролог, 4:44. У полуразвалившейся церкви ждёт толпа; телега ещё не остановилась. Внутренняя мысль аватара «Партийный выдвиженец»; показывается текстом без озвучки.', 'Вид развалин разочаровывает; председатель ещё не знает, где внутри устроены склад и кабинет.', 'Закончить дорожный портрет аватара его первой реакцией на место будущей ответственности.', 'Уверенная речь человека со связями и привычкой к согласованиям; канцелярит не должен становиться пародией. Не называть назначение церкви, склада и пристройки до остановки.', 'ai/prologue-avatar-thoughts-draft.md#8-партийный-выдвиженец', 1, NULL, 0, 805);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.start.prologue.student.t1', 'scene.start.prologue', 'scene', 'caption', 'chairman', NULL, NULL, NULL, 'start.prologue.t1', 'male', 'Выбран avatar.key = student; адрес пролога 0:06.', NULL, 'Какая-то чертовщина... Мы же никуда не сворачивали.', 'Дорожный пролог, 0:06. В плотном тумане одна и та же берёза прошла слева второй раз. Внутренняя мысль аватара «Студент»; показывается текстом без озвучки.', 'Председатель замечает невозможное повторение дороги, но не понимает переход.', 'Сразу дать голос выбранного аватара и показать странность без объяснения.', 'Образованная, слегка тревожная речь; теория должна прояснять наблюдение, а не становиться афоризмом. Не называть портал и не объяснять природу тумана.', 'ai/prologue-avatar-thoughts-draft.md#6-студент', 1, NULL, 0, 103);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.start.prologue.student.t2', 'scene.start.prologue', 'scene', 'caption', 'chairman', NULL, NULL, NULL, 'start.prologue.t2', 'male', 'Выбран avatar.key = student; адрес пролога 0:29.', 'scene.start.prologue.student.t1', 'Зима малоснежная, талой воды мало — вот грунт и держит. В обычный год мы бы так легко не доехали.', 'Дорожный пролог, 0:29. После взгляда назад видна обычная мокрая дорога; на экране уже указан апрель 1931 года. Внутренняя мысль аватара «Студент»; показывается текстом без озвучки.', 'Малоснежная зима объясняет необычно лёгкий путь и будущую весеннюю распутицу.', 'Объяснить игроку различие первой и обычной весны как знание героя, а не подсказку механики.', 'Образованная, слегка тревожная речь; теория должна прояснять наблюдение, а не становиться афоризмом. Сохранить причинную связь: мало снега — мало талой воды — дорога временно держит.', 'ai/prologue-avatar-thoughts-draft.md#6-студент', 1, NULL, 0, 203);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.start.prologue.student.t3', 'scene.start.prologue', 'scene', 'caption', 'chairman', NULL, NULL, NULL, 'start.prologue.t3', 'male', 'Выбран avatar.key = student; адрес пролога 0:48.', 'scene.start.prologue.student.t2', 'Кладбище старше колхоза. Значит, у этого места есть история, которой в районной справке не было.', 'Дорожный пролог, 0:48. Кладбище видно за голыми деревьями слева от дороги. Внутренняя мысль аватара «Студент»; показывается текстом без озвучки.', 'Кладбище показывает, что село и его связи старше колхоза.', 'Показать отношение аватара к прошлому незнакомого или родного села.', 'Образованная, слегка тревожная речь; теория должна прояснять наблюдение, а не становиться афоризмом. Не приписывать незнакомым жителям мысли, память или намерения.', 'ai/prologue-avatar-thoughts-draft.md#6-студент', 1, NULL, 0, 303);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.start.prologue.student.t4', 'scene.start.prologue', 'scene', 'caption', 'chairman', NULL, NULL, NULL, 'start.prologue.t4', 'male', 'Выбран avatar.key = student; адрес пролога 1:47.', 'scene.start.prologue.student.t3', 'Вода, пашня, лес и дорога — условия лучше, чем мне представлялось. Тем важнее понять, почему хозяйство не работает.', 'Дорожный пролог, 1:47. После выхода из рощи открылись река, озеро, село и широкие поля. Внутренняя мысль аватара «Студент»; показывается текстом без озвучки.', 'Природные условия хорошие; одной землёй разруху хозяйства не объяснить.', 'Дать каждому аватару увидеть в одной панораме свой способ взяться за хозяйство.', 'Образованная, слегка тревожная речь; теория должна прояснять наблюдение, а не становиться афоризмом. Не обещать конкретный юнит или решение до осмотра хозяйства.', 'ai/prologue-avatar-thoughts-draft.md#6-студент', 1, NULL, 0, 403);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.start.prologue.student.t5', 'scene.start.prologue', 'scene', 'caption', 'chairman', NULL, NULL, NULL, 'start.prologue.t5', 'male', 'Выбран avatar.key = student; адрес пролога 2:42.', 'scene.start.prologue.student.t4', 'Вся связь с районом идёт через один мост. Надёжность всей дороги зависит от него.', 'Дорожный пролог, 2:42. Телега только что съехала с единственного моста через реку. Внутренняя мысль аватара «Студент»; показывается текстом без озвучки.', 'Вся связь с районом зависит от одной переправы.', 'Показать, какой риск или человеческое последствие первым замечает аватар.', 'Образованная, слегка тревожная речь; теория должна прояснять наблюдение, а не становиться афоризмом. Сохранить единственность моста и зависимость связи с районом.', 'ai/prologue-avatar-thoughts-draft.md#6-студент', 1, NULL, 0, 503);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.start.prologue.student.t6', 'scene.start.prologue', 'scene', 'caption', 'chairman', NULL, NULL, NULL, 'start.prologue.t6', 'male', 'Выбран avatar.key = student; адрес пролога 3:07.', 'scene.start.prologue.student.t5', 'По справке — пашня. На деле — залежь. Пожалуй, знакомство с местной отчётностью уже началось.', 'Дорожный пролог, 3:07. У дороги видна залежь, а дальше читаются большие заброшенные поля. Внутренняя мысль аватара «Студент»; показывается текстом без озвучки.', 'Пашню не обрабатывали уже несколько сезонов.', 'Перевести обещание панорамы в первое конкретное разочарование.', 'Образованная, слегка тревожная речь; теория должна прояснять наблюдение, а не становиться афоризмом. Не называть точную причину запустения: герой её ещё не знает.', 'ai/prologue-avatar-thoughts-draft.md#6-студент', 1, NULL, 0, 603);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.start.prologue.student.t7', 'scene.start.prologue', 'scene', 'caption', 'chairman', NULL, NULL, NULL, 'start.prologue.t7', 'male', 'Выбран avatar.key = student; адрес пролога 3:56.', 'scene.start.prologue.student.t6', 'Корма не хватает — это слышно. А люди уже ждут от меня ответа, хотя я ещё ни о чём не спросил.', 'Дорожный пролог, 3:56. Слева уже слышно голодных коров; жители у дороги молча смотрят вслед телеге. Внутренняя мысль аватара «Студент»; показывается текстом без озвучки.', 'Скоту не хватает корма, а жители только наблюдают за новым председателем.', 'Дать первый живой сигнал хозяйственной беды и реакцию аватара на молчаливую встречу.', 'Образованная, слегка тревожная речь; теория должна прояснять наблюдение, а не становиться афоризмом. Не угадывать мысли жителей и не утверждать, что они уже что-либо рассказали.', 'ai/prologue-avatar-thoughts-draft.md#6-студент', 1, NULL, 0, 703);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.start.prologue.student.t8', 'scene.start.prologue', 'scene', 'caption', 'chairman', NULL, NULL, NULL, 'start.prologue.t8', 'male', 'Выбран avatar.key = student; адрес пролога 4:44.', 'scene.start.prologue.student.t7', 'Я ожидал увидеть хотя бы контору. А здесь полуразвалившаяся церковь и всё село у дверей.', 'Дорожный пролог, 4:44. У полуразвалившейся церкви ждёт толпа; телега ещё не остановилась. Внутренняя мысль аватара «Студент»; показывается текстом без озвучки.', 'Вид развалин разочаровывает; председатель ещё не знает, где внутри устроены склад и кабинет.', 'Закончить дорожный портрет аватара его первой реакцией на место будущей ответственности.', 'Образованная, слегка тревожная речь; теория должна прояснять наблюдение, а не становиться афоризмом. Не называть назначение церкви, склада и пристройки до остановки.', 'ai/prologue-avatar-thoughts-draft.md#6-студент', 1, NULL, 0, 803);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.start.prologue.villager.t1', 'scene.start.prologue', 'scene', 'caption', 'chairman', NULL, NULL, NULL, 'start.prologue.t1', 'male', 'Выбран avatar.key = villager; адрес пролога 0:06.', NULL, 'Вот же чертовщина: ехали прямо, а берёза опять слева.', 'Дорожный пролог, 0:06. В плотном тумане одна и та же берёза прошла слева второй раз. Внутренняя мысль аватара «Деревенский»; показывается текстом без озвучки.', 'Председатель замечает невозможное повторение дороги, но не понимает переход.', 'Сразу дать голос выбранного аватара и показать странность без объяснения.', 'Простая деревенская речь без диалекта; мыслит землёй, погодой и сроком. Не называть портал и не объяснять природу тумана.', 'ai/prologue-avatar-thoughts-draft.md#4-деревенский', 1, NULL, 0, 101);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.start.prologue.villager.t2', 'scene.start.prologue', 'scene', 'caption', 'chairman', NULL, NULL, NULL, 'start.prologue.t2', 'male', 'Выбран avatar.key = villager; адрес пролога 0:29.', 'scene.start.prologue.villager.t1', 'Снега зимой почти не было — потому и дорога держит. В обычную весну сюда из района так легко не доедешь.', 'Дорожный пролог, 0:29. После взгляда назад видна обычная мокрая дорога; на экране уже указан апрель 1931 года. Внутренняя мысль аватара «Деревенский»; показывается текстом без озвучки.', 'Малоснежная зима объясняет необычно лёгкий путь и будущую весеннюю распутицу.', 'Объяснить игроку различие первой и обычной весны как знание героя, а не подсказку механики.', 'Простая деревенская речь без диалекта; мыслит землёй, погодой и сроком. Сохранить причинную связь: мало снега — мало талой воды — дорога временно держит.', 'ai/prologue-avatar-thoughts-draft.md#4-деревенский', 1, NULL, 0, 201);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.start.prologue.villager.t3', 'scene.start.prologue', 'scene', 'caption', 'chairman', NULL, NULL, NULL, 'start.prologue.t3', 'male', 'Выбран avatar.key = villager; адрес пролога 0:48.', 'scene.start.prologue.villager.t2', 'Погост на месте. Значит, дорога всё-таки вывела куда надо.', 'Дорожный пролог, 0:48. Кладбище видно за голыми деревьями слева от дороги. Внутренняя мысль аватара «Деревенский»; показывается текстом без озвучки.', 'Кладбище показывает, что село и его связи старше колхоза.', 'Показать отношение аватара к прошлому незнакомого или родного села.', 'Простая деревенская речь без диалекта; мыслит землёй, погодой и сроком. Не приписывать незнакомым жителям мысли, память или намерения.', 'ai/prologue-avatar-thoughts-draft.md#4-деревенский', 1, NULL, 0, 301);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.start.prologue.villager.t4', 'scene.start.prologue', 'scene', 'caption', 'chairman', NULL, NULL, NULL, 'start.prologue.t4', 'male', 'Выбран avatar.key = villager; адрес пролога 1:47.', 'scene.start.prologue.villager.t3', 'Вода рядом, лес есть, поля широкие. Земля здесь не виновата.', 'Дорожный пролог, 1:47. После выхода из рощи открылись река, озеро, село и широкие поля. Внутренняя мысль аватара «Деревенский»; показывается текстом без озвучки.', 'Природные условия хорошие; одной землёй разруху хозяйства не объяснить.', 'Дать каждому аватару увидеть в одной панораме свой способ взяться за хозяйство.', 'Простая деревенская речь без диалекта; мыслит землёй, погодой и сроком. Не обещать конкретный юнит или решение до осмотра хозяйства.', 'ai/prologue-avatar-thoughts-draft.md#4-деревенский', 1, NULL, 0, 401);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.start.prologue.villager.t5', 'scene.start.prologue', 'scene', 'caption', 'chairman', NULL, NULL, NULL, 'start.prologue.t5', 'male', 'Выбран avatar.key = villager; адрес пролога 2:42.', 'scene.start.prologue.villager.t4', 'Мост ещё держится. Подъезды к нему размоет раньше, чем настил. За ними и следить.', 'Дорожный пролог, 2:42. Телега только что съехала с единственного моста через реку. Внутренняя мысль аватара «Деревенский»; показывается текстом без озвучки.', 'Вся связь с районом зависит от одной переправы.', 'Показать, какой риск или человеческое последствие первым замечает аватар.', 'Простая деревенская речь без диалекта; мыслит землёй, погодой и сроком. Сохранить единственность моста и зависимость связи с районом.', 'ai/prologue-avatar-thoughts-draft.md#4-деревенский', 1, NULL, 0, 501);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.start.prologue.villager.t6', 'scene.start.prologue', 'scene', 'caption', 'chairman', NULL, NULL, NULL, 'start.prologue.t6', 'male', 'Выбран avatar.key = villager; адрес пролога 3:07.', 'scene.start.prologue.villager.t5', 'Земля не пропала. За один год всю залежь не поднять; начнём с сухого края.', 'Дорожный пролог, 3:07. У дороги видна залежь, а дальше читаются большие заброшенные поля. Внутренняя мысль аватара «Деревенский»; показывается текстом без озвучки.', 'Пашню не обрабатывали уже несколько сезонов.', 'Перевести обещание панорамы в первое конкретное разочарование.', 'Простая деревенская речь без диалекта; мыслит землёй, погодой и сроком. Не называть точную причину запустения: герой её ещё не знает.', 'ai/prologue-avatar-thoughts-draft.md#4-деревенский', 1, NULL, 0, 601);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.start.prologue.villager.t7', 'scene.start.prologue', 'scene', 'caption', 'chairman', NULL, NULL, NULL, 'start.prologue.t7', 'male', 'Выбран avatar.key = villager; адрес пролога 3:56.', 'scene.start.prologue.villager.t6', 'Коровы ревут — корма им не хватает. Вот с этого и начнём.', 'Дорожный пролог, 3:56. Слева уже слышно голодных коров; жители у дороги молча смотрят вслед телеге. Внутренняя мысль аватара «Деревенский»; показывается текстом без озвучки.', 'Скоту не хватает корма, а жители только наблюдают за новым председателем.', 'Дать первый живой сигнал хозяйственной беды и реакцию аватара на молчаливую встречу.', 'Простая деревенская речь без диалекта; мыслит землёй, погодой и сроком. Не угадывать мысли жителей и не утверждать, что они уже что-либо рассказали.', 'ai/prologue-avatar-thoughts-draft.md#4-деревенский', 1, NULL, 0, 701);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.start.prologue.villager.t8', 'scene.start.prologue', 'scene', 'caption', 'chairman', NULL, NULL, NULL, 'start.prologue.t8', 'male', 'Выбран avatar.key = villager; адрес пролога 4:44.', 'scene.start.prologue.villager.t7', 'Церковь-то как запустили. И свои смотрят, будто чужого прислали.', 'Дорожный пролог, 4:44. У полуразвалившейся церкви ждёт толпа; телега ещё не остановилась. Внутренняя мысль аватара «Деревенский»; показывается текстом без озвучки.', 'Вид развалин разочаровывает; председатель ещё не знает, где внутри устроены склад и кабинет.', 'Закончить дорожный портрет аватара его первой реакцией на место будущей ответственности.', 'Простая деревенская речь без диалекта; мыслит землёй, погодой и сроком. Не называть назначение церкви, склада и пристройки до остановки.', 'ai/prologue-avatar-thoughts-draft.md#4-деревенский', 1, NULL, 0, 801);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.start.prologue.worker.t1', 'scene.start.prologue', 'scene', 'caption', 'chairman', NULL, NULL, NULL, 'start.prologue.t1', 'male', 'Выбран avatar.key = worker; адрес пролога 0:06.', NULL, 'Колея без поворотов, а берёза попалась второй раз. Чертовщина какая-то.', 'Дорожный пролог, 0:06. В плотном тумане одна и та же берёза прошла слева второй раз. Внутренняя мысль аватара «Рабочий»; показывается текстом без озвучки.', 'Председатель замечает невозможное повторение дороги, но не понимает переход.', 'Сразу дать голос выбранного аватара и показать странность без объяснения.', 'Заводская деловитость и производственные слова; не превращать каждую мысль в сравнение с заводом. Не называть портал и не объяснять природу тумана.', 'ai/prologue-avatar-thoughts-draft.md#5-рабочий', 1, NULL, 0, 102);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.start.prologue.worker.t2', 'scene.start.prologue', 'scene', 'caption', 'chairman', NULL, NULL, NULL, 'start.prologue.t2', 'male', 'Выбран avatar.key = worker; адрес пролога 0:29.', 'scene.start.prologue.worker.t1', 'Снега было мало, вода быстро ушла — поэтому дорога держит. В обычную весну здесь вязли бы по ось.', 'Дорожный пролог, 0:29. После взгляда назад видна обычная мокрая дорога; на экране уже указан апрель 1931 года. Внутренняя мысль аватара «Рабочий»; показывается текстом без озвучки.', 'Малоснежная зима объясняет необычно лёгкий путь и будущую весеннюю распутицу.', 'Объяснить игроку различие первой и обычной весны как знание героя, а не подсказку механики.', 'Заводская деловитость и производственные слова; не превращать каждую мысль в сравнение с заводом. Сохранить причинную связь: мало снега — мало талой воды — дорога временно держит.', 'ai/prologue-avatar-thoughts-draft.md#5-рабочий', 1, NULL, 0, 202);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.start.prologue.worker.t3', 'scene.start.prologue', 'scene', 'caption', 'chairman', NULL, NULL, NULL, 'start.prologue.t3', 'male', 'Выбран avatar.key = worker; адрес пролога 0:48.', 'scene.start.prologue.worker.t2', 'Кладбище у дороги. Село ещё не видно, а люди здесь жили задолго до колхоза.', 'Дорожный пролог, 0:48. Кладбище видно за голыми деревьями слева от дороги. Внутренняя мысль аватара «Рабочий»; показывается текстом без озвучки.', 'Кладбище показывает, что село и его связи старше колхоза.', 'Показать отношение аватара к прошлому незнакомого или родного села.', 'Заводская деловитость и производственные слова; не превращать каждую мысль в сравнение с заводом. Не приписывать незнакомым жителям мысли, память или намерения.', 'ai/prologue-avatar-thoughts-draft.md#5-рабочий', 1, NULL, 0, 302);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.start.prologue.worker.t4', 'scene.start.prologue', 'scene', 'caption', 'chairman', NULL, NULL, NULL, 'start.prologue.t4', 'male', 'Выбран avatar.key = worker; адрес пролога 1:47.', 'scene.start.prologue.worker.t3', 'Вода, лес, поля — всё рядом. Подвоз наладить, работу поставить — и хозяйство пойдёт.', 'Дорожный пролог, 1:47. После выхода из рощи открылись река, озеро, село и широкие поля. Внутренняя мысль аватара «Рабочий»; показывается текстом без озвучки.', 'Природные условия хорошие; одной землёй разруху хозяйства не объяснить.', 'Дать каждому аватару увидеть в одной панораме свой способ взяться за хозяйство.', 'Заводская деловитость и производственные слова; не превращать каждую мысль в сравнение с заводом. Не обещать конкретный юнит или решение до осмотра хозяйства.', 'ai/prologue-avatar-thoughts-draft.md#5-рабочий', 1, NULL, 0, 402);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.start.prologue.worker.t5', 'scene.start.prologue', 'scene', 'caption', 'chairman', NULL, NULL, NULL, 'start.prologue.t5', 'male', 'Выбран avatar.key = worker; адрес пролога 2:42.', 'scene.start.prologue.worker.t4', 'Один мост держит всю связь с районом. Встанет он — встанет и снабжение.', 'Дорожный пролог, 2:42. Телега только что съехала с единственного моста через реку. Внутренняя мысль аватара «Рабочий»; показывается текстом без озвучки.', 'Вся связь с районом зависит от одной переправы.', 'Показать, какой риск или человеческое последствие первым замечает аватар.', 'Заводская деловитость и производственные слова; не превращать каждую мысль в сравнение с заводом. Сохранить единственность моста и зависимость связи с районом.', 'ai/prologue-avatar-thoughts-draft.md#5-рабочий', 1, NULL, 0, 502);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.start.prologue.worker.t6', 'scene.start.prologue', 'scene', 'caption', 'chairman', NULL, NULL, NULL, 'start.prologue.t6', 'male', 'Выбран avatar.key = worker; адрес пролога 3:07.', 'scene.start.prologue.worker.t5', 'Поле большое, а работы на нём нет. Здесь не один участок встал — всё хозяйство стоит.', 'Дорожный пролог, 3:07. У дороги видна залежь, а дальше читаются большие заброшенные поля. Внутренняя мысль аватара «Рабочий»; показывается текстом без озвучки.', 'Пашню не обрабатывали уже несколько сезонов.', 'Перевести обещание панорамы в первое конкретное разочарование.', 'Заводская деловитость и производственные слова; не превращать каждую мысль в сравнение с заводом. Не называть точную причину запустения: герой её ещё не знает.', 'ai/prologue-avatar-thoughts-draft.md#5-рабочий', 1, NULL, 0, 602);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.start.prologue.worker.t7', 'scene.start.prologue', 'scene', 'caption', 'chairman', NULL, NULL, NULL, 'start.prologue.t7', 'male', 'Выбран avatar.key = worker; адрес пролога 3:56.', 'scene.start.prologue.worker.t6', 'Сначала корм для скота. Потом разберусь, где работа встала.', 'Дорожный пролог, 3:56. Слева уже слышно голодных коров; жители у дороги молча смотрят вслед телеге. Внутренняя мысль аватара «Рабочий»; показывается текстом без озвучки.', 'Скоту не хватает корма, а жители только наблюдают за новым председателем.', 'Дать первый живой сигнал хозяйственной беды и реакцию аватара на молчаливую встречу.', 'Заводская деловитость и производственные слова; не превращать каждую мысль в сравнение с заводом. Не угадывать мысли жителей и не утверждать, что они уже что-либо рассказали.', 'ai/prologue-avatar-thoughts-draft.md#5-рабочий', 1, NULL, 0, 702);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.start.prologue.worker.t8', 'scene.start.prologue', 'scene', 'caption', 'chairman', NULL, NULL, NULL, 'start.prologue.t8', 'male', 'Выбран avatar.key = worker; адрес пролога 4:44.', 'scene.start.prologue.worker.t7', 'Церковь еле стоит. Начинать придётся с развалин.', 'Дорожный пролог, 4:44. У полуразвалившейся церкви ждёт толпа; телега ещё не остановилась. Внутренняя мысль аватара «Рабочий»; показывается текстом без озвучки.', 'Вид развалин разочаровывает; председатель ещё не знает, где внутри устроены склад и кабинет.', 'Закончить дорожный портрет аватара его первой реакцией на место будущей ответственности.', 'Заводская деловитость и производственные слова; не превращать каждую мысль в сравнение с заводом. Не называть назначение церкви, склада и пристройки до остановки.', 'ai/prologue-avatar-thoughts-draft.md#5-рабочий', 1, NULL, 0, 802);
